        break;
      case 158: // DictPair -> String, ':', DictExpr
{
  CurrentSemanticValue.blk = gen_dictpair(ValueStack[ValueStack.Depth-3].blk, ValueStack[ValueStack.Depth-1].blk);
}
        break;
      case 159: // DictPair -> String
{
  CurrentSemanticValue.blk = gen_dictpair(
      ValueStack[ValueStack.Depth-1].blk,
      BLOCK(
          gen_op_simple(POP),
          gen_op_simple(DUP2),
          gen_op_simple(DUP2),
          gen_op_simple(INDEX)));
}
        break;
      case 160: // DictPair -> BINDING, ':', DictExpr
{
  CurrentSemanticValue.blk = gen_dictpair(
      gen_location(CurrentLocationSpan, gen_op_unbound(LOADV, libjq.jv_string_value(ValueStack[ValueStack.Depth-3].literal))),
      ValueStack[ValueStack.Depth-1].blk);
  FreeLiteral(ValueStack[ValueStack.Depth-3].literal);
}
        break;
      case 161: // DictPair -> BINDING
{
  CurrentSemanticValue.blk = gen_dictpair(
      gen_const(ValueStack[ValueStack.Depth-1].literal),
      gen_location(CurrentLocationSpan, gen_op_unbound(LOADV, libjq.jv_string_value(ValueStack[ValueStack.Depth-1].literal))));
}
        break;
      case 162: // DictPair -> IDENT
{
  CurrentSemanticValue.blk = gen_dictpair(
      gen_const(libjq.jv_copy(ValueStack[ValueStack.Depth-1].literal)),
      gen_index(gen_noop(), gen_const(ValueStack[ValueStack.Depth-1].literal)));
}
        break;
      case 163: // DictPair -> "$__loc__"
{
  CurrentSemanticValue.blk = gen_dictpair(
      gen_const(libjq.jv_string("__loc__")),
      gen_loc_object(CurrentLocationSpan));
}
        break;
      case 164: // DictPair -> Keyword
{
  CurrentSemanticValue.blk = gen_dictpair(
      gen_const(libjq.jv_copy(ValueStack[ValueStack.Depth-1].literal)),
      gen_index(gen_noop(), gen_const(ValueStack[ValueStack.Depth-1].literal)));
}
        break;
      case 165: // DictPair -> '(', Query, ')', ':', DictExpr
{
  var message = check_object_key(ValueStack[ValueStack.Depth-4].blk);
  if (libjq.jv_is_valid(message)) {
    FAIL(LocationStack[LocationStack.Depth-4], libjq.jv_string_value(message));
  }
  libjq.jv_free(message);
  CurrentSemanticValue.blk = gen_dictpair(ValueStack[ValueStack.Depth-4].blk, ValueStack[ValueStack.Depth-1].blk);
}
        break;
      case 166: // DictPair -> error, ':', DictExpr
{
  FAIL(
      ObjectEntryRecoveryLocation(LocationStack[LocationStack.Depth-3]),
      "May need parentheses around object key expression");
  CurrentSemanticValue.blk = ValueStack[ValueStack.Depth-1].blk;
}
        break;
      case 167: // DictExpr -> DictExpr, '|', DictExpr
{
  CurrentSemanticValue.blk = block_join(ValueStack[ValueStack.Depth-3].blk, ValueStack[ValueStack.Depth-1].blk);
}
        break;
      case 168: // DictExpr -> Expr
{
  CurrentSemanticValue.blk = ValueStack[ValueStack.Depth-1].blk;
}
        break;
    }
#pragma warning restore 162, 1522
  }

  protected override string TerminalToString(int terminal)
  {
    if (aliases != null && aliases.ContainsKey(terminal))
        return aliases[terminal];
    else if (((JqParserToken)terminal).ToString() != terminal.ToString(CultureInfo.InvariantCulture))
        return ((JqParserToken)terminal).ToString();
    else
        return CharToString((char)terminal);
  }

}
}
